use std::fmt::Display;

trait Encode {
    fn encode_with<T: Display>(&self, x: T) -> String;
}

struct Prefix(String);

impl Encode for Prefix {
    fn encode_with<T: Display>(&self, x: T) -> String {
        format!("{}: {}", self.0, x)
    }
}

fn main() {
    let encoders: Vec<Box<dyn Encode>> = vec![
        Box::new(Prefix("v".into())),
    ];
    for e in &encoders {
        println!("{}", e.encode_with(42));
    }
}
